#!/usr/bin/env python3
"""Analysis helpers for ditaa shape probing."""
import sys
sys.path.insert(0, '/tmp/probe')
import png as P

def load(path):
    w,h,ch,ct,px,chunks = P.load(path)
    return w,h,ch,px

def pix(px,w,x,y,ch=3):
    i=(y*w+x)*ch
    return px[i:i+ch]

def is_black(p):
    return p[0]<128 and p[1]<128 and p[2]<128

def is_bg(p, bg=(255,255,255)):
    return abs(p[0]-bg[0])<8 and abs(p[1]-bg[1])<8 and abs(p[2]-bg[2])<8

def bbox_black(px,w,h,ch=3):
    xs=[];ys=[]
    for y in range(h):
        for x in range(w):
            if is_black(pix(px,w,x,y,ch)):
                xs.append(x);ys.append(y)
    if not xs: return None
    return min(xs),min(ys),max(xs),max(ys)

def column_ys(px,w,h,x,ch=3):
    return [y for y in range(h) if is_black(pix(px,w,x,y,ch))]

def row_xs(px,w,h,y,ch=3):
    return [x for x in range(w) if is_black(pix(px,w,x,y,ch))]

def dump_outline(px,w,h,ch=3, x0=None,x1=None):
    """For each x in range, list black y runs."""
    x0 = 0 if x0 is None else x0
    x1 = w-1 if x1 is None else x1
    for x in range(x0,x1+1):
        ys = column_ys(px,w,h,x,ch)
        if ys:
            runs=[]
            s=ys[0];prev=ys[0]
            for y in ys[1:]:
                if y==prev+1: prev=y
                else: runs.append((s,prev)); s=y; prev=y
            runs.append((s,prev))
            print(x, runs)

def colors(px,w,h,ch=3):
    from collections import Counter
    c=Counter()
    for y in range(h):
        for x in range(w):
            c[bytes(pix(px,w,x,y,ch))]+=1
    return c

def ascii_art(px,w,h,ch=3,x0=0,y0=0,x1=None,y1=None,bg=(255,255,255)):
    x1=w-1 if x1 is None else x1
    y1=h-1 if y1 is None else y1
    out=[]
    for y in range(y0,y1+1):
        row=''
        for x in range(x0,x1+1):
            p=pix(px,w,x,y,ch)
            if is_bg(p,bg): row+='.'
            elif is_black(p): row+='#'
            else: row+='+'  # antialiased/other
        out.append(row)
    return '\n'.join(out)

